select admi.user_name doctor,info.*,card.End_Time as treedate,role.role_name from yh_user_reginfo info inner join yh_user_role_power role_power on info.user_code=role_power.userId inner join yh_user_role role on role_power.roleId=role.role_id inner join yh_user_make_card card on info.user_code=card.User_Code inner join yh_user_admin_info admi on card.doctor=admi.id
info.User_Type=5
and info.Org_Code LIKE CONCAT(#{orgCode},'%')
and info.lock_flag = #{lockFlag}
and info.name LIKE CONCAT('%',#{name},'%')
and info.user_name LIKE CONCAT('%',#{userName},'%')
and admi.user_code=#{doctor}
and info.mobile=#{mobile}
order by info.reg_time desc LIMIT #{page},#{limit}

