SELECT a.Entry_Time FROM ( (SELECT Entry_Time FROM yh_user_temperature WHERE E_User_Id=#{usercode} ORDER BY Entry_Time DESC LIMIT 1) UNION (SELECT Entry_Time FROM yh_user_oxygen WHERE E_User_Id=#{usercode} ORDER BY Entry_Time DESC LIMIT 1) UNION (SELECT Entry_Time FROM yh_user_bmi WHERE E_User_Id=#{usercode} ORDER BY Entry_Time DESC LIMIT 1) UNION (SELECT Entry_Time FROM yh_user_bloodpressure WHERE E_User_Id=#{usercode} ORDER BY Entry_Time DESC LIMIT 1) UNION (SELECT Entry_Time FROM yh_user_bloodsuger WHERE E_User_Id=#{usercode} ORDER BY Entry_Time DESC LIMIT 1) UNION (SELECT Entry_Time FROM yh_user_heart_rate WHERE E_User_Id=#{usercode} ORDER BY Entry_Time DESC LIMIT 1) UNION (SELECT Entry_Time FROM yh_user_body_fat WHERE E_User_Id=#{usercode} ORDER BY Entry_Time DESC LIMIT 1) UNION (SELECT Entry_Time FROM yh_user_bloodfat WHERE E_User_Id=#{usercode} ORDER BY Entry_Time DESC LIMIT 1) UNION (SELECT inertTime FROM yh_user_renalfunction WHERE user_id=#{usercode} ORDER BY inertTime DESC LIMIT 1) UNION (SELECT insertTime FROM yh_user_liverfunction WHERE user_id=#{usercode} ORDER BY insertTime DESC LIMIT 1) UNION (SELECT Entry_Time FROM yh_user_ecg WHERE E_User_Id=#{usercode} ORDER BY Entry_Time DESC LIMIT 1) UNION (SELECT `addDate` FROM yh_user_uba WHERE E_User_Id=#{usercode} ORDER BY `addDate` DESC LIMIT 1) UNION (SELECT insertTime FROM yh_user_otherfunction WHERE user_id=#{usercode} ORDER BY insertTime DESC LIMIT 1)
)AS a
ORDER BY a.Entry_Time DESC LIMIT 1

    select t1.*
  	from yh_user_make_card t1
