         and t1.Org_Id=#{orgCode}

select * from ( select regin.user_code,regin.user_name,regin.name,tree.Org_Code,regin.reg_time,card.End_Time as Add_Date,regin.lock_flag,ydatr.classify,ydatr.qtime,card.Org_Id from yh_user_reginfo as regin LEFT JOIN yh_user_make_card as card on regin.user_code=card.User_Code LEFT JOIN yh_org_tree as tree ON regin.Org_code=tree.Org_Code LEFT JOIN yh_user_admin_info as yuai ON yuai.id=card.doctor LEFT JOIN (SELECT a.* FROM ( SELECT * FROM yh_disease_assess_total_report2 ORDER BY qtime DESC ) AS a GROUP BY a.user_code ) as ydatr ON regin.user_code = ydatr.user_code where yuai.user_code=#{userCode,jdbcType=VARCHAR} and regin.`name` is not null and regin.birth_date is not null
and card.Org_Id in
#{item}
and (card.End_Time > current_date or card.End_Time is null)
and card.End_Time < current_date
and regin.user_name like '%${userName}%'
and regin.name like '%${name}%'
and regin.lock_flag = #{lockFlag}
and regin.reg_time between #{regdate1} AND #{regdate2}
order by reg_time desc) w group by user_code having w.user_code IN(select userId from yh_user_role_power where roleId = 17) order by w.reg_time desc

